<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\PublicOrderService;

$pdo=Database::connection();$token=trim((string)($_GET['t']??''));$s=$pdo->prepare('SELECT rt.*,t.name tenant_name,t.id tenant_id,t.status tenant_status FROM restaurant_tables rt JOIN tenants t ON t.id=rt.tenant_id WHERE rt.qr_token=? LIMIT 1');$s->execute([$token]);$table=$s->fetch();if(!$table||$table['tenant_status']!=='active'||$table['status']==='inactive'){http_response_code(404);exit('Mesa não encontrada ou indisponível.');}$tenantId=(int)$table['tenant_id'];
$cartKey='table:'.$token;if(!isset($_SESSION['public_carts'][$cartKey]))$_SESSION['public_carts'][$cartKey]=[];$cart=&$_SESSION['public_carts'][$cartKey];$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada.';else{
        try{$action=(string)($_POST['action']??'');if($action==='add'){$id=(int)($_POST['product_id']??0);$p=$pdo->prepare('SELECT id FROM products WHERE id=? AND tenant_id=? AND active=1');$p->execute([$id,$tenantId]);if(!$p->fetchColumn())throw new RuntimeException('Produto indisponível.');$cart[$id]=min(50,(int)($cart[$id]??0)+1);header('Location: /mesa.php?t='.urlencode($token).'#carrinho');exit;}if($action==='qty'){$id=(int)($_POST['product_id']??0);$qty=max(0,min(50,(int)($_POST['qty']??0)));if($qty===0)unset($cart[$id]);else$cart[$id]=$qty;header('Location: /mesa.php?t='.urlencode($token).'#carrinho');exit;}if($action==='checkout'){$payload=[];foreach($cart as$id=>$qty)$payload[]=['product_id'=>(int)$id,'qty'=>(int)$qty];$result=(new PublicOrderService())->createTable($token,$payload,['name'=>(string)($_POST['name']??''),'phone'=>(string)($_POST['phone']??'')]);$cart=[];header('Location: /pedido.php?t='.urlencode($result['public_token']),true,303);exit;}}catch(Throwable $e){$error=$e->getMessage();}
    }
}
$c=$pdo->prepare('SELECT * FROM categories WHERE tenant_id=? AND active=1 ORDER BY sort_order,name');$c->execute([$tenantId]);$categories=$c->fetchAll();$p=$pdo->prepare('SELECT * FROM products WHERE tenant_id=? AND active=1 ORDER BY category_id,name');$p->execute([$tenantId]);$products=$p->fetchAll();$byId=[];foreach($products as$prod)$byId[(int)$prod['id']]=$prod;$cartTotal=0;foreach($cart as$id=>$qty)if(isset($byId[$id]))$cartTotal+=(int)$byId[$id]['price_cents']*(int)$qty;
$tab=$pdo->prepare('SELECT tb.id,tb.label,(SELECT COALESCE(SUM(o.total_cents),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") total,(SELECT COALESCE(SUM(CASE WHEN o.payment_status<>"paid" THEN o.total_cents ELSE 0 END),0) FROM orders o WHERE o.tab_id=tb.id AND o.status<>"cancelled") unpaid FROM tabs tb WHERE tb.tenant_id=? AND tb.table_id=? AND tb.status="open" LIMIT 1');$tab->execute([$tenantId,$table['id']]);$openTab=$tab->fetch();
function mesa_money(int $c):string{return 'R$ '.number_format($c/100,2,',','.');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0b0f14"><title><?= Security::e($table['tenant_name']) ?> · <?= Security::e($table['name']) ?></title><link rel="manifest" href="/manifest.webmanifest"><link rel="stylesheet" href="/assets/app.css"><style>.shell{max-width:1120px;margin:auto;padding:20px 16px 90px}.hero{padding:30px;border-radius:26px;background:linear-gradient(135deg,#181e2a,#11151d);border:1px solid var(--line);margin-bottom:18px}.layout2{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,1fr);gap:18px}.product{display:grid;grid-template-columns:1fr auto;gap:14px;align-items:center}.product+.product{border-top:1px solid var(--line);padding-top:14px;margin-top:14px}.cart{position:sticky;top:16px}.qty{display:flex;gap:6px}.qty input{width:64px}@media(max-width:820px){.layout2{grid-template-columns:1fr}.cart{position:static}}</style></head><body><main class="shell"><section class="hero"><div class="brand">EventMenu <span>Premium</span></div><p class="muted"><?= Security::e($table['tenant_name']) ?></p><h1><?= Security::e($table['name']) ?></h1><p>Faça seu pedido pelo QR da mesa.</p><?php if($openTab):?><div class="alert ok">Comanda #<?= (int)$openTab['id'] ?> aberta · Total <?= mesa_money((int)$openTab['total']) ?> · Em aberto <?= mesa_money((int)$openTab['unpaid']) ?></div><?php endif;?></section><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?><div class="layout2"><section><?php foreach($categories as$cat):?><article class="card" style="margin-bottom:16px"><h2><?= Security::e($cat['name']) ?></h2><?php foreach($products as$prod):if((int)$prod['category_id']!==(int)$cat['id'])continue;?><div class="product"><div><strong><?= Security::e($prod['name']) ?></strong><div class="muted"><?= Security::e($prod['description']) ?></div><strong><?= mesa_money((int)$prod['price_cents']) ?></strong></div><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?= (int)$prod['id'] ?>"><button class="primary">Adicionar</button></form></div><?php endforeach;?></article><?php endforeach;?></section><aside id="carrinho" class="card cart"><h2>Pedido da mesa</h2><?php if(!$cart):?><p class="muted">Adicione itens.</p><?php else:?><?php foreach($cart as$id=>$qty):if(!isset($byId[$id]))continue;$i=$byId[$id];?><div class="product"><div><strong><?= Security::e($i['name']) ?></strong><div class="muted"><?= mesa_money((int)$i['price_cents']*(int)$qty) ?></div></div><form method="post" class="qty"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="qty"><input type="hidden" name="product_id" value="<?= (int)$id ?>"><input type="number" name="qty" min="0" max="50" value="<?= (int)$qty ?>"><button class="secondary">OK</button></form></div><?php endforeach;?><hr style="border-color:var(--line)"><p><strong>Total <span style="float:right"><?= mesa_money($cartTotal) ?></span></strong></p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="checkout"><label class="span-2">Seu nome <small class="muted">(opcional)</small><input name="name"></label><label class="span-2">Telefone <small class="muted">(opcional)</small><input name="phone"></label><button class="primary span-2">Enviar para a comanda</button></form><p class="muted">Após enviar, você poderá pagar online se a casa tiver um gateway habilitado ou pagar no caixa.</p><?php endif;?></aside></div></main><script>if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{});}</script></body></html>
